use crate::bridge::extern_c_api as extern_api;
use data::*;

use proptest::prelude::*;

/// container for component's incoming port values
pub struct PreStateContainer {
  pub api_request_sample: Drone_Lifecycle_Governor::Lifecycle_Request_Sample
}

/// setter for component's incoming port values
pub fn put_concrete_inputs_container(container: PreStateContainer)
{
  put_request_sample(container.api_request_sample);
}

/// setter for component's incoming port values
pub fn put_concrete_inputs(request_sample: Drone_Lifecycle_Governor::Lifecycle_Request_Sample)
{
  put_request_sample(request_sample);
}

/// setter for IN DataPort
pub fn put_request_sample(value: Drone_Lifecycle_Governor::Lifecycle_Request_Sample)
{
  *extern_api::IN_request_sample.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// getter for OUT DataPort
pub fn get_qualified_request() -> Drone_Lifecycle_Governor::Qualified_Request
{
  return extern_api::OUT_qualified_request.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}
